import { Component } from 'react'
import { Container, CustomText } from '../../../components'
// import { get as lodashGet } from 'lodash/object'
import Cookies from 'universal-cookie'
import { LANG_STRINGS } from '../../../lang'
import { HelpStyle } from './index.style'
import { Row } from '../../../commonStyle/index.style'
import { HELP_TYPES, COVID_HELP } from './constants'
import { AgentColorPallette } from '../../../configs/colorPallete'
import searchBuilder from '../../../helpers/queryBuilder'
import { MAIL_ID, PHONE_NUMBER, WHATS_APP_NUMBER } from '../Profile/constants'
import { WHATS_APP_URL } from '../../../constants/appUrls'
import { connect } from 'react-redux'
// import { checkIsGojekDriver } from '../../../helpers/checkAgentTags'

const cookies = new Cookies()
class Help extends Component {
  handleHelpUrl = (help) => {
    if (help.path) {
      if (help.isTour) {
        help.cookieName.forEach(cookieName =>
          cookies.remove(cookieName, {
            path: '/'
          })
        )
      }
      this.props.history.push({
        pathname: help.path,
        state: {
          productCode: help.productCode || ''
        }
      })
    } else if (help.type === 'whatsapp') {
      const queryString = searchBuilder({
        phone: WHATS_APP_NUMBER
      })
      const url = encodeURI(`${WHATS_APP_URL}${queryString}`)
      // this to start timer for whatsAppBtn and disable the btn for 60 sec.
      window.open(url, '_blank')
      return true
    } else if (help.type === 'phone') {
      const telphone = `tel:${PHONE_NUMBER}`
      window.open(telphone, '_blank')
    } else if (help.type === 'email') {
      const mailContent = `mailto:${encodeURIComponent(MAIL_ID)}`
      window.open(mailContent, '_blank')
    }
  }

  render () {
    const helpSection = [
      ...COVID_HELP,
      ...HELP_TYPES
    ]
    return (
      <Container
        title={LANG_STRINGS.selectHelp}
        displayBackButton
        hideBottomTabs
      >
        <HelpStyle>
          {
            helpSection.map(help => (
              <Row key={help.name} className='help-box' onClick={() => this.handleHelpUrl(help)}>
                <div className='help-icon'>
                  {
                    help.isIcon ? <i className={help.icon} />
                      : (<img src={help.icon} alt={help.name} />)
                  }
                </div>
                <CustomText
                  color={AgentColorPallette.black}
                  size='14px'
                  weight={800}
                >
                  {help.name}
                </CustomText>
              </Row>
            ))
          }
        </HelpStyle>
      </Container>
    )
  }
}

export default connect(
  state => ({
    agentDetails: state.User.agentDetails
  }),
  {

  }
)(Help)
